head.b:skin:
/* ===========================================================================
   Masala Deutsch — a Blogger theme built for long, data-heavy analysis posts.
   No third-party JavaScript. No packed/encrypted footer scripts. No web fonts.

   Two design constraints came from real failures on this blog:
   1. Index pages render post SNIPPETS, never full bodies. Rendering full
      bodies blew Blogger's per-page budget on 30-530KB posts and the post
      list silently came back EMPTY.
   2. NO automatic dark mode, at any level. The posts force a white background
      with !important, so a theme-level dark block flips the text to near-white
      while the surface stays white -- the page renders blank. See the note on
      the palette below.
   =========================================================================== */

:root{
  --ink:#0B1F2D;        /* headings, body text  */
  --ink-soft:#43535F;   /* secondary text       */
  --accent:#2251FF;     /* links, rules         */
  --accent-ink:#1B3FCC; /* link hover           */
  --cyan:#00A9F4;       /* kickers, eyebrow rules */
  --bg:#FFFFFF;
  --bg-alt:#F4F7FB;
  --line:#D9E1E8;
  --hero:#0B1F2D;
  --hero-ink:#FFFFFF;
  --serif:Georgia,'Times New Roman',serif;
  --sans:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Arial,sans-serif;
  --wrap:1080px;
  --measure:70ch;
}
/* NO dark mode. Deliberately, and this was learned the hard way twice.
   The published posts carry their own `body{background:#fff!important}`
   override. A theme-level prefers-color-scheme block flips --ink to near-white
   but CANNOT flip the surface, because the post's !important wins -- so every
   heading and link renders white-on-white and the page reads as blank.
   A theme declares <body>; it does not get the last word on it.
   Light only. Do not re-add a dark block without first removing the
   force-white rules from all 69 post bodies. */

*,*::before,*::after{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font:17px/1.65 var(--serif);
  -webkit-text-size-adjust:100%}
img{max-width:100%;height:auto}
a{color:var(--accent);text-underline-offset:2px}
a:hover{color:var(--accent-ink)}
.wrap:not(.post-body *){max-width:var(--wrap);margin-inline:auto;padding-inline:20px}

/* ---- Header ---------------------------------------------------------- */
.site-head{border-bottom:1px solid var(--line);background:var(--bg);
  position:sticky;top:0;z-index:20}
.site-head .wrap{display:flex;align-items:center;gap:18px;
  justify-content:space-between;min-height:60px;flex-wrap:wrap}
.site-title{font-family:var(--sans);font-weight:700;font-size:1rem;
  letter-spacing:.02em;text-transform:uppercase;color:var(--ink);text-decoration:none}
.site-title span{color:var(--accent)}
/* gs-brand-header-v1 (2026-11-10): VertiStrat logo + link to the main website */
.site-title{display:inline-flex;align-items:center;gap:10px;text-transform:none;letter-spacing:-.01em;font-size:1.15rem}
.site-title svg{flex:none}
.site-title .wm{color:var(--ink)}
.site-title .sub{color:var(--ink);opacity:.65;font-weight:500;font-size:.75rem;letter-spacing:.12em;text-transform:uppercase;padding-left:10px;border-left:1px solid var(--line)}
.site-nav{margin-left:auto}
.site-main{font-family:var(--sans);font-size:.82rem;font-weight:600;text-decoration:none;border:1px solid var(--accent);border-radius:8px;padding:6px 12px;white-space:nowrap}
.site-main:hover{background:var(--accent);color:#fff}
.site-nav{font-family:var(--sans);font-size:.82rem;display:flex;gap:16px;flex-wrap:wrap}
.site-nav a{text-decoration:none}
.site-nav a:hover{text-decoration:underline}

/* ---- Hero / featured -------------------------------------------------- */
.hero:not(.post-body *){background:var(--hero);color:var(--hero-ink);padding:72px 0 66px;margin-bottom:8px}
.hero:not(.post-body *) .kicker{font-family:var(--sans);font-size:.7rem;letter-spacing:.18em;
  text-transform:uppercase;font-weight:700;color:var(--cyan);margin-bottom:14px}
.hero:not(.post-body *) h2{font-size:2.5rem;line-height:1.12;margin:0 0 16px;letter-spacing:-.02em;font-weight:300}
.hero:not(.post-body *) h2 strong{font-weight:700}
.hero:not(.post-body *) h2 a{color:var(--hero-ink);text-decoration:none}
.hero:not(.post-body *) h2 a:hover{text-decoration:underline}
.hero:not(.post-body *) p{color:#C7D4DF;max-width:var(--measure);margin:0 0 16px}
.hero:not(.post-body *) .more{font-family:var(--sans);font-size:.82rem;font-weight:700;
  color:#7FA5FF;text-decoration:none;letter-spacing:.04em;text-transform:uppercase}

/* ---- Post list (index) ------------------------------------------------ */
.section-label{font-family:var(--sans);font-size:.7rem;letter-spacing:.18em;
  text-transform:uppercase;font-weight:700;color:var(--ink);
  border-top:2px solid var(--ink);padding-top:10px;margin:52px 0 0;
  display:block}
.card:not(.post-body *){border-bottom:1px solid var(--line);padding:32px 0}
.card:not(.post-body *):last-child{border-bottom:none}
.card:not(.post-body *) h3{font-size:1.5rem;line-height:1.22;margin:0 0 8px;letter-spacing:-.015em;font-weight:400}
.card:not(.post-body *) h3 a{color:var(--ink);text-decoration:none}
.card:not(.post-body *) h3 a:hover{color:var(--accent)}
.card:not(.post-body *) .meta{font-family:var(--sans);font-size:.75rem;color:var(--ink-soft);
  margin-bottom:8px;font-variant-numeric:tabular-nums}
.card:not(.post-body *) p{margin:0 0 10px;color:var(--ink-soft);max-width:var(--measure)}
.card:not(.post-body *) .more{font-family:var(--sans);font-size:.78rem;font-weight:700;
  text-decoration:none;letter-spacing:.04em;text-transform:uppercase}

/* ---- Single post ------------------------------------------------------ */
.post-head{padding:52px 0 18px;border-bottom:2px solid var(--ink);margin-bottom:32px}
.post-head h1{font-size:2.6rem;line-height:1.14;margin:0 0 14px;letter-spacing:-.025em;font-weight:300}
.post-head h1 strong{font-weight:700}
.post-head .meta{font-family:var(--sans);font-size:.78rem;color:var(--ink-soft)}
.post-body{font-size:1.02rem}
.gs-topics{margin:2rem 0 0;padding-top:1rem;border-top:1px solid #e2e2e2;
 display:flex;flex-wrap:wrap;gap:.45rem;align-items:center}
.gs-topics .k{font-size:.68rem;letter-spacing:.14em;text-transform:uppercase;
 font-weight:700;color:#595959;margin-right:.3rem}
.gs-topics a{font-size:.8rem;font-weight:600;color:#0B1F2D;background:#F4F7FB;
 padding:.35rem .7rem;border-radius:2px;text-decoration:none;white-space:nowrap}
.gs-topics a:hover{background:#e6ecf5}
.post-body p{max-width:var(--measure)}
.post-body h2,.post-body h3{line-height:1.3}
/* Long analysis posts carry wide tables; they scroll in their own box so the
   page body never scrolls sideways on a phone. */
.post-body table{max-width:100%;border-collapse:collapse}
.post-body .table-scroll,.post-body div[style*="overflow"]{overflow-x:auto}
.post-body img{height:auto}

/* ---- Gadget slots in the page body -----------------------------------
   The whole reason this theme exists. Blogger's modern themes (Contempo,
   Soho, Emporio, Notable) allow NO gadgets in the page body, so a
   topic index cannot be placed with the content. These sections do. */
.slot{margin:26px 0}
.slot .widget{margin-bottom:20px}
.slot h2,.slot h3{font-family:var(--sans);font-size:.7rem;letter-spacing:.18em;
  text-transform:uppercase;font-weight:700;color:var(--ink-soft);margin:0 0 10px}
.slot ul{margin:0;padding-left:1.1rem}
.slot li{margin-bottom:5px}

/* ---- Browse-by-topic block (an HTML gadget in the main-bottom slot) ----
   Sits BELOW the recent-article list: newest work first, whole archive after. */
.browse{border-top:2px solid var(--ink);margin-top:40px;padding-top:20px}
.browse-head h2{font-family:var(--sans);font-size:1.15rem;font-weight:700;
  margin:0 0 6px;color:var(--ink);letter-spacing:-.01em}
.browse-head p{font-family:var(--sans);font-size:.85rem;color:var(--ink-soft);margin:0}
.topics{display:grid;grid-template-columns:repeat(auto-fit,minmax(255px,1fr));
  gap:20px 28px;margin:26px 0 8px}
.topic h3{font-family:var(--sans);font-size:.72rem;letter-spacing:.14em;
  text-transform:uppercase;font-weight:700;color:var(--ink);margin:0 0 8px;
  border-bottom:2px solid var(--accent);padding-bottom:5px}
.topic h3 span{color:var(--ink-soft);font-weight:400;letter-spacing:0}
.topic ul{margin:0;padding:0;list-style:none}
.topic li{margin-bottom:6px;line-height:1.4}
.topic a{font-size:.92rem;text-decoration:none;color:var(--ink)}
.topic a:hover{color:var(--accent);text-decoration:underline}
.topics{display:block;margin:26px 0 8px}
.topic{margin:0}
.topic>summary{cursor:pointer;list-style:none;display:flex;align-items:baseline;gap:.7rem;flex-wrap:wrap;border-top:2px solid var(--ink);padding:14px 0;position:relative;padding-right:28px}
.topic>summary::-webkit-details-marker{display:none}
.topic>summary::after{content:"+";position:absolute;right:0;top:14px;font-size:1.3em;font-weight:700;color:var(--accent);line-height:1}
.topic[open]>summary::after{content:"\2212"}
.topic>summary h3{font-family:var(--sans);font-size:1.05rem;font-weight:700;margin:0;color:var(--ink);text-transform:none;letter-spacing:-.01em;border-bottom:none;padding-bottom:0}
.topic ul{margin:14px 0 20px;padding:0;list-style:none}

/* ---- Pager & footer --------------------------------------------------- */
.pager{display:flex;justify-content:space-between;gap:16px;
  border-top:2px solid var(--ink);margin-top:34px;padding:16px 0 0;
  font-family:var(--sans);font-size:.8rem;font-weight:700}
.pager a{text-decoration:none}
.site-foot{border-top:1px solid var(--line);margin-top:48px;padding:24px 0 40px;
  font-family:var(--sans);font-size:.78rem;color:var(--ink-soft)}
.site-foot .widget{margin-bottom:12px}

@media (max-width:640px){
  body{font-size:16px}
  .hero:not(.post-body *) h2{font-size:1.55rem}
  .post-head h1{font-size:1.6rem}
  .site-head{position:static}
}

/* gs-dup-headline-v1 — hide the theme-rendered post title only on posts that
   carry their own <h1> in the body. 75 of 91 posts do; the other 16 rely on the
   theme title, so a blanket rule would leave them untitled. :has() expresses the
   condition exactly; browsers without it fall back to showing both, which is
   today's behaviour. */
.widget.Blog:has(.post-body h1) .post-head h1 { display: none !important; }

/* gs-readable-ads-v1 (2026-10-09) — keep the post readable with Auto ads on.
   1. The post header (date + rule) lines up with the article column instead of
      running the full 1080px width above a 760px article.
   2. Auto-placed ads sit inside that same column, centred, with clear space and
      a small "Advertisement" label above them, so an ad never reads as part of
      a table, chart or stat box.
   3. Anchor (bottom-of-screen) ads cannot cover the last lines of a post.
   Nothing here creates, moves or hides an ad; AdSense still decides placement. */
.post-head{max-width:760px;margin-inline:auto;padding:28px 0 12px;
  border-bottom:1px solid var(--line);margin-bottom:22px}
.widget.Blog:has(.post-body h1) .post-head{padding-top:18px;margin-bottom:8px}
.gs-topics{max-width:760px;margin-inline:auto}
.post-body .google-auto-placed{display:block;clear:both;max-width:760px;
  margin:2.4rem auto !important;padding-top:1.5rem !important;
  border-top:1px solid var(--line);position:relative;text-align:center}
.post-body .google-auto-placed::before{content:"Advertisement";position:absolute;
  top:.35rem;left:0;font:700 .6rem/1 var(--sans);letter-spacing:.16em;
  text-transform:uppercase;color:#8a8a8a}
.post-body ins.adsbygoogle{margin-inline:auto}
body{padding-bottom:env(safe-area-inset-bottom)}
body:has(ins.adsbygoogle[data-anchor-status]) .site-foot{padding-bottom:110px}
@media (max-width:640px){
  .post-head{padding-top:16px}
  .post-body .google-auto-placed{margin:1.8rem 0 !important}
}
/* Tables that already sit in their own scrolling wrapper (.gb-tblwrap, .tw)
   lay out as normal tables, so long text cells wrap instead of being cut off
   at the right edge; the wrapper still scrolls when a table is truly wide. */
.post-body .gb-tblwrap>table,.post-body .tw>table{display:table;width:100%;min-width:0}
.post-body .gb-tblwrap td,.post-body .gb-tblwrap th{white-space:normal}
@media (max-width:640px){
  .post-body .gb-tblwrap>table,.post-body .tw>table{min-width:600px}
}
/* BEGIN theme-module: gs-table-template-v1 */
/* gs-table-template-v1 (2026-10-26) — one readable template for every post table,
   and no ad containers inside tables.
   1. Every post table gets the same look: dark header, light row stripes, clear
      padding, text left-aligned, numbers right-aligned in tabular figures. Per-post
      table styles (accent headers, right-aligned text cells) are overridden so a
      reader sees one table style across the blog. Inline row highlights survive.
   2. The gs-table-guard-v1 script wraps unwrapped tables in .gs-tblwrap (scrolls on
      phones), marks number cells .gs-num and moves any Auto-ads container that
      lands inside a table to just after the table.
   3. Empty (unfilled) Auto-ads containers collapse instead of showing an empty
      "Advertisement" box; the label and spacing apply only to filled ads. */
#Blog1 .post-body .gs-tblwrap{margin:1.2rem 0}
#Blog1 .post-body .gs-tblwrap,#Blog1 .post-body .gb-tblwrap,#Blog1 .post-body .tw{overflow-x:auto;-webkit-overflow-scrolling:touch;max-width:100%}
#Blog1 .post-body .gs-tblwrap,#Blog1 .post-body .gb-tblwrap,#Blog1 .post-body .tw{contain:inline-size}
#Blog1 .post-body table.gs-t{border-collapse:collapse!important;width:100%;max-width:100%;
  font-family:var(--sans);font-size:.88rem;line-height:1.45;font-variant-numeric:tabular-nums;margin:0}
#Blog1 .post-body table.gs-t th,#Blog1 .post-body table.gs-t td{text-align:left!important;
  vertical-align:top;padding:.5rem .7rem!important;border:0!important;
  border-bottom:1px solid #dcdcdc!important;white-space:normal;word-break:normal;overflow-wrap:anywhere}
#Blog1 .post-body table.gs-t thead th,#Blog1 .post-body table.gs-t tr.gs-head>th{
  background:#1f2328!important;color:#fff!important;font-weight:600;vertical-align:bottom}
#Blog1 .post-body table.gs-t tbody tr:nth-child(even)>td{background:#f6f7f8}
#Blog1 .post-body table.gs-t tbody th{background:transparent;color:inherit;font-weight:600}
#Blog1 .post-body table.gs-t .gs-num{text-align:right!important}
#Blog1 .post-body table.gs-t td.gs-num{white-space:nowrap}
#Blog1 .post-body table.gs-t caption{caption-side:top;text-align:left;font-weight:600;padding:0 0 .4rem}
@media (max-width:640px){
  #Blog1 .post-body table.gs-t{font-size:.84rem}
  #Blog1 .post-body .gb-tblwrap>table.gs-t:not(.gs-wide),#Blog1 .post-body .tw>table.gs-t:not(.gs-wide){min-width:0}
  #Blog1 .post-body table.gs-t.gs-wide{min-width:560px}
}
.post-body .google-auto-placed:not(:has(ins[data-ad-status="filled"])){
  margin:0!important;padding:0!important;border:0!important;min-height:0}
.post-body .google-auto-placed:not(:has(ins[data-ad-status="filled"]))::before{content:none}
/* END theme-module: gs-table-template-v1 */
/* BEGIN theme-module: gs-readable-v1 */
/* gs-readable-v1 (2026-10-26) — readability fixes measured across all 376 posts
   (out/research/theme-audit-2026-10-26.md).
   1. Line length: paragraphs ran to a median 80 characters on desktop and list items
      had no cap at all (over 95 characters in 234 posts). Text blocks now stop at 64ch
      (about 70 characters in Georgia).
   2. Long links, file paths and code no longer push the page sideways on phones.
   3. Grey note text (.gb-note in 196 posts at 3.3:1, and 13 one-off note classes at
      3.0-3.9:1) and the ad label (3.4:1) meet WCAG AA contrast (4.5:1).
   4. Links to a section land below the sticky header instead of under it.
   5. Header navigation links get a 24px tap target. */
#Blog1 .post-body{--measure:64ch;overflow-wrap:break-word}
#Blog1 .post-body :is(ul,ol):not(.crows)>li,#Blog1 .post-body blockquote{max-width:var(--measure)}
#Blog1 .post-body :is(a,code,kbd,samp){overflow-wrap:anywhere}
#Blog1 .post-body pre{max-width:100%;overflow-x:auto;white-space:pre}
#Blog1 .post-body :is(canvas,iframe,video,embed,object){max-width:100%}
#Blog1 .post-body .gb-note{color:#5f6871}
#Blog1 .post-body .legend-note{color:#55594f}
#Blog1 .post-body :is(.rb-note,.mp-note,.et-note,.si-note,.tr-note,.mg-note,.gh-note,.em-note,.evg-note,.gh2-note,.im-note,.block-note,p.cite){color:#5f6871}
.post-body .google-auto-placed::before{color:#6b6b6b;font-size:.66rem}
@media (min-width:641px){
  #Blog1 .post-body :is(h1,h2,h3,h4,[id]){scroll-margin-top:76px}
}
.site-nav a{display:inline-block;padding:4px 0;min-height:24px}
/* END theme-module: gs-readable-v1 */

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//

body.script:
//
(function(){
  var b=document.getElementById('gs-sd-blog'); if(!b) return;
  var home=b.getAttribute('data-home')||(location.origin+'/');
  if(home.charAt(home.length-1)!=='/') home+='/';
  var cl=document.querySelector('link[rel="canonical"]');
  var canon=(cl&&cl.href)||location.href.split('#')[0];
  function meta(sel){var m=document.querySelector(sel);return (m&&m.content)||'';}
  // Description, in order of trustworthiness. Blogger auto-generates
  // og:description from the raw top of the post body, which on this blog is
  // the index link and the eyebrow line -- pure chrome. The standfirst is the
  // hand-written one-paragraph summary, so it outranks og: here and og: is
  // kept only as a last resort.
  function clean(t){ return t.replace(/\s+/g,' ').trim(); }
  var desc=meta('meta[name="description"]');
  if(!desc){ var sf=document.querySelector('.post-body .standfirst, .standfirst');
    if(sf) desc=clean(sf.textContent).slice(0,300); }
  if(!desc) desc=clean(meta('meta[property="og:description"]')).slice(0,300);
  var img =meta('meta[property="og:image"]');
  // Google drops an article whose headline runs past ~110 characters, so trim
  // on a word boundary rather than shipping something it will ignore.
  function head(t){ if(!t||t.length<=110) return t;
    var c=t.slice(0,110); var i=c.lastIndexOf(' ');
    return (i>60?c.slice(0,i):c).replace(/[\s,;:-]+$/,''); }

  var person={"@type":"Person","@id":home+"#person",
    "name":"Umashankar Triplicane Dwarakanathan",
    "url":home+"p/about.html",
    "jobTitle":"Investment Promotion & Energy-Sector Leader",
    "sameAs":["https://www.linkedin.com/in/umashankar-tdrickshaw-moc/",
              "https://github.com/herrrickshaw"]};

  var site={"@type":"WebSite","@id":home+"#website","url":home,
    "name":b.getAttribute('data-title')||document.title,
    "inLanguage":"en","publisher":{"@id":home+"#person"},
    "potentialAction":{"@type":"SearchAction",
      "target":{"@type":"EntryPoint","urlTemplate":home+"search?q={search_term_string}"},
      "query-input":"required name=search_term_string"}};

  // document.title is prefixed with the blog name ("Thinking global, living
  // local: <post>"); prefer the bare post title where the post loop gave us one.
  var pd=document.querySelector('.gs-sd-post');
  var pageName=(pd&&pd.getAttribute('data-title'))||document.title;
  var page={"@type":"WebPage","@id":canon+"#webpage","url":canon,
    "name":pageName,"isPartOf":{"@id":home+"#website"},"inLanguage":"en"};
  if(desc) page.description=desc;
  if(img)  page.primaryImageOfPage={"@type":"ImageObject","url":img};

  // Blogger emits one blog-level description on every page. A per-page
  // description is what actually earns the click, and each post already has a
  // hand-written one in its standfirst. Override both tags with it where we
  // have one. Google renders this; social scrapers do not run JS, which is why
  // the blog-level tag stays in the markup as the floor rather than being
  // replaced at the source.
  if(desc){
    var dm=document.querySelector('meta[name="description"]');
    if(!dm){ dm=document.createElement('meta'); dm.setAttribute('name','description');
             document.head.appendChild(dm); }
    dm.setAttribute('content', desc);
    var om=document.querySelector('meta[property="og:description"]');
    if(om) om.setAttribute('content', desc);
  }

  var graph=[site,person,page];

  var p=pd;
  if(p){
    var art={"@type":"BlogPosting","@id":canon+"#article",
      "headline":head(p.getAttribute('data-title')||document.title),
      "url":p.getAttribute('data-url')||canon,
      "mainEntityOfPage":{"@id":canon+"#webpage"},
      "isPartOf":{"@id":home+"#website"},
      "author":{"@id":home+"#person"},
      "publisher":{"@id":home+"#person"},
      "inLanguage":"en"};
    var pub=p.getAttribute('data-published'); if(pub) art.datePublished=pub;
    // Posts carry their own revision stamp. Use it where it exists; leave
    // dateModified off entirely where it does not, rather than inventing one.
    var t=document.querySelector('time[itemprop="dateModified"][datetime]');
    if(t) art.dateModified=t.getAttribute('datetime');
    if(desc) art.description=desc;
    var im=img||p.getAttribute('data-image'); if(im) art.image=[im];
    graph.push(art);
    page.mainEntity={"@id":canon+"#article"};
  }

  var s=document.createElement('script');
  s.type='application/ld+json';
  s.textContent=JSON.stringify({"@context":"https://schema.org","@graph":graph});
  document.head.appendChild(s);
})();
